mapper.select:
SELECT id, script_name AS name, project_id AS project_id, script_type AS type, status, create_time AS created_at, update_time AS updated_at FROM ai_storyboard_script WHERE deleted = 0 AND tenant_id = #{tenantId} AND create_by = #{creatorId} AND project_id = #{projectId}
AND script_name LIKE CONCAT('%', #{keyword}, '%')
AND script_type IN
#{scriptType}
AND status = #{status}
ORDER BY TRIM( CASE WHEN LOCATE('爆款复刻', script_name) > 0 THEN LEFT(script_name, LOCATE('爆款复刻', script_name) - 1) WHEN LOCATE('脚本模板库', script_name) > 0 THEN LEFT(script_name, LOCATE('脚本模板库', script_name) - 1) WHEN LOCATE('AI原创', script_name) > 0 THEN LEFT(script_name, LOCATE('AI原创', script_name) - 1) ELSE script_name END ) ASC, update_time DESC, id DESC
ORDER BY update_time DESC, id DESC
